"""Proxy receipt vectors generated by the Go proxy
(proxy/internal/receipts/sdk_vectors_test.go keeps the file in step with
the proxy's encoding)."""
from __future__ import annotations

import dataclasses
import json
from pathlib import Path

import pytest

from ovara_sdk.types import PortableReceipt
from ovara_sdk.verify import (
    _receipt_canonical_v1,
    _receipt_canonical_v2,
    _receipt_version,
    _rfc3339_to_unix_nano,
    compute_receipt_digest,
    receipt_key_id,
    verify_receipt,
)

VECTORS_PATH = Path(__file__).resolve().parents[2] / "testdata" / "receipts_v2.json"
FILE = json.loads(VECTORS_PATH.read_text(encoding="utf-8"))
PUB = FILE["public_key"]
VECTORS = FILE["vectors"]


def test_vector_set_covers_the_cases():
    names = {v["name"] for v in VECTORS}
    for want in ("v1_allow", "v2_attempt", "v2_outcome_reasons_approver",
                 "v2_tampered_approver", "v2_signed_sig_v1"):
        assert want in names
    assert any(v["valid"] for v in VECTORS)
    assert any(not v["valid"] for v in VECTORS)


def test_key_id_matches_go():
    assert receipt_key_id(PUB) == FILE["key_id"]


@pytest.mark.parametrize("vec", VECTORS, ids=[v["name"] for v in VECTORS])
def test_vector(vec):
    receipt = PortableReceipt.from_json(vec["line"])
    assert verify_receipt(receipt, PUB) is vec["valid"], vec["why"]
    assert _receipt_version(receipt) == vec["version"]
    if vec["version"] == 2:
        payload = _receipt_canonical_v2(receipt)
    else:
        payload = _receipt_canonical_v1(receipt).encode("utf-8")
    assert payload.hex() == vec["canonical_hex"]
    assert compute_receipt_digest(receipt) == vec["digest"]


@pytest.mark.parametrize("vec", [v for v in VECTORS if v["valid"]], ids=lambda v: v["name"])
def test_any_field_change_breaks_a_valid_vector(vec):
    receipt = PortableReceipt.from_json(vec["line"])
    for f in dataclasses.fields(receipt):
        if f.name in ("signature", "v"):
            continue
        val = getattr(receipt, f.name)
        if isinstance(val, list):
            changed = val + ["x"]
        elif isinstance(val, int) and not isinstance(val, bool):
            changed = val + 1
        elif f.name == "timestamp":
            changed = val.replace("Z", "+00:01") if val.endswith("Z") else val[:-6] + "Z"
        elif val is None:
            continue  # setting a v2 field on v1 is covered by the downgrade vectors
        else:
            changed = val + "x"
        tampered = dataclasses.replace(receipt, **{f.name: changed})
        assert verify_receipt(tampered, PUB) is False, f.name


def test_unicode_and_empty_values_present():
    outcome = PortableReceipt.from_json(
        next(v for v in VECTORS if v["name"] == "v2_outcome_reasons_approver")["line"]
    )
    assert "" in outcome.reasons
    assert any(ord(c) > 0xFFFF for c in "".join(outcome.reasons))  # an astral character
    assert outcome.resp_bytes == -1


def test_timestamp_nanos_match_go():
    # Offsets and trailing-zero-trimmed fractions, as Go's RFC3339Nano writes them.
    assert _rfc3339_to_unix_nano("2026-01-02T08:34:07.000000001+05:30") == \
        _rfc3339_to_unix_nano("2026-01-02T03:04:07.000000001Z")
    assert _rfc3339_to_unix_nano("2026-01-02T03:04:07.5Z") == 1767323047_500000000


def test_v2_fields_with_sig_v1_refused_even_when_v1_signature_is_good():
    vec = next(v for v in VECTORS if v["name"] == "v1_allow")
    base = PortableReceipt.from_json(vec["line"])
    assert verify_receipt(base, PUB) is True
    for name, val in (("v", 2), ("rule", "r"), ("kid", FILE["key_id"]), ("reasons", ["a"]),
                      ("req_bytes", 1), ("resp_bytes", -1), ("approver", "a")):
        assert verify_receipt(dataclasses.replace(base, **{name: val}), PUB) is False, name


def test_from_json_rejects_unknown_keys():
    line = json.loads(VECTORS[0]["line"])
    line["extra"] = 1
    with pytest.raises(ValueError):
        PortableReceipt.from_json(line)


def test_lone_surrogate_is_refused():
    vec = next(v for v in VECTORS if v["name"] == "v2_attempt")
    r = PortableReceipt.from_json(vec["line"])
    assert verify_receipt(dataclasses.replace(r, rule="\ud800"), PUB) is False
